97	    private Set<Pet> pets;
98	
99	    /**
100	     * Transient, write-only request flag: when {@code true}, creating this owner is allowed even if
101	     * another owner already shares the same last name and address. Never persisted or returned.
102	     */
103	    @Transient
104	    private boolean sharesHousehold;
