178	    /**
179	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
180	     * owner's {@code registrationDate} (falling back to the current date when no registration date
181	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
182	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
183	     */
184	    @Transient
185	    public String getAgeBand() {
186	        if (this.birthDate == null) {
187	            return null;
188	        }
189	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
190	        int age = Period.between(this.birthDate, reference).getYears();
191	        if (age < 18) {
192	            return "MINOR";
193	        }
194	        if (age < 65) {
