232	    /**
233	     * Derive the owner's {@code membershipPoints}: a score starting at 0 that adds 2 when an email
234	     * is present, adds 1 when the owner's name was unique at creation time ({@code namesakeCount}
235	     * is 0), adds 2 when the owner belongs to a household of three or more members, and adds 3 when
236	     * the owner's tenure exceeds 365 days (measured from the {@code registrationDate} to today).
237	     */
238	    @Transient
239	    public Integer getMembershipPoints() {
240	        int points = 0;
241	        if (this.email != null && !this.email.isBlank()) {
242	            points += 2;
243	        }
244	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
245	            points += 1;
246	        }
247	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
248	            points += 2;
249	        }
250	        if (hasTenureOver365Days()) {
251	            points += 3;
252	        }
253	        return points;
254	    }
255	
256	    /**
257	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 4, by mapping the owner's
258	     * {@code membershipPoints}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
259	     * points, and level 4 for 6 or more points.
260	     */
261	    @Transient
262	    public Integer getMembershipLevel() {
263	        int points = getMembershipPoints();
264	        if (points <= 1) {
265	            return 1;
266	        }
267	        if (points <= 3) {
268	            return 2;
269	        }
270	        if (points <= 5) {
271	            return 3;
272	        }
273	        return 4;
274	    }
275	
276	    /**
277	     * Whether the owner's tenure, measured as the number of whole days from {@code registrationDate}
278	     * to today, exceeds 365 days — worth 3 membership points. A missing {@code registrationDate}
279	     * (and therefore zero tenure) never qualifies.
280	     */
281	    @Transient
282	    private boolean hasTenureOver365Days() {
283	        if (this.registrationDate == null) {
284	            return false;
285	        }
286	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
287	    }
288	
289	    /**
290	     * Derive the owner's read-only {@code checkDigit}: a single Luhn check digit (0-9) computed
291	     * over the digits contained in the owner's {@code customerCode}. Non-digit characters (the
292	     * '-' separators and letters) are ignored. Returns {@code null} when no {@code customerCode}
293	     * has been assigned yet.
294	     */
295	    @Transient
296	    public Integer getCheckDigit() {
297	        if (this.customerCode == null) {
298	            return null;
299	        }
300	        int sum = 0;
301	        boolean dbl = true;
302	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
303	            char c = this.customerCode.charAt(i);
304	            if (c < '0' || c > '9') {
305	                continue;
306	            }
307	            int d = c - '0';
308	            if (dbl) {
309	                d *= 2;
310	                if (d > 9) {
311	                    d -= 9;
312	                }
313	            }
314	            sum += d;
315	            dbl = !dbl;
316	        }
317	        return (10 - (sum % 10)) % 10;
318	    }
319	
320	    /**
321	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners:
322	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone and
323	     * email are already stored in their canonical (E.164 / lower-cased) form, so a {@code null} or
324	     * blank email contributes an empty segment and an absent {@code householdId} an empty segment.
325	     * Two owners are duplicates only when their whole {@code identityKey} is equal.
326	     */
327	    @Transient
328	    public String getIdentityKey() {
329	        String telephonePart = this.telephone == null ? "" : this.telephone;
330	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
331	        String householdPart = this.householdId == null ? "" : this.householdId;
332	        return telephonePart + "|" + emailPart + "|" + householdPart;
333	    }
