370	    }
371	
372	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
373	        this.possibleDuplicateOf = possibleDuplicateOf;
374	    }
375	
376	    public boolean isSharesHousehold() {
377	        return this.sharesHousehold;
378	    }
379	
380	    public void setSharesHousehold(boolean sharesHousehold) {
381	        this.sharesHousehold = sharesHousehold;
382	    }
383	
384	    protected Set<Pet> getPetsInternal() {
385	        if (this.pets == null) {
386	            this.pets = new HashSet<>();
387	        }
388	        return this.pets;
389	    }
390	
391	    protected void setPetsInternal(Set<Pet> pets) {
392	        this.pets = pets;
393	    }
394	
395	    public List<Pet> getPets() {
396	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
397	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
398	        return Collections.unmodifiableList(sortedPets);
399	    }
400	
401	    public void setPets(List<Pet> pets) {
402	        this.pets = new HashSet<>(pets);
403	    }
404	
405	    public void addPet(Pet pet) {
406	        getPetsInternal().add(pet);
407	        pet.setOwner(this);
408	    }
409	
410	    /**
411	     * Return the Pet with the given name, or null if none found for this Owner.
412	     *
413	     * @param name to test
414	     * @return true if pet name is already in use
415	     */
416	    public Pet getPet(String name) {
417	        return getPet(name, false);
418	    }
419	
420	    /**
421	     * Return the Pet with the given name, or null if none found for this Owner.
422	     *
423	     * @param name to test
424	     * @return true if pet name is already in use
425	     */
426	    public Pet getPet(String name, boolean ignoreNew) {
427	        name = name.toLowerCase();
428	        for (Pet pet : getPetsInternal()) {
429	            if (!ignoreNew || !pet.isNew()) {
430	                String compName = pet.getName();
431	                compName = compName.toLowerCase();
432	                if (compName.equals(name)) {
433	                    return pet;
434	                }
435	            }
436	        }
437	        return null;
438	    }
439	
440	    public Pet getPet(Integer petId) {
441	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
442	    }
443	
444	    @Override
445	    public String toString() {
446	        return new ToStringCreator(this)
447	
448	            .append("id", this.getId())
449	            .append("new", this.isNew())
450	            .append("lastName", this.getLastName())
451	            .append("firstName", this.getFirstName())
452	            .append("address", this.address)
453	            .append("city", this.city)
454	            .append("telephone", this.telephone)
455	            .toString();
456	    }
457	}
